mapper.select:
SELECT c.id, c.post_id AS postId, c.user_id AS userId, c.parent_id AS parentId, c.reply_to_user_id AS replyToUserId, c.content, c.like_count AS likeCount, c.create_time AS createTime, u.nickname AS authorNickname, u.avatar AS authorAvatar, ru.nickname AS replyToNickname FROM forum_comment c LEFT JOIN sys_user u ON c.user_id = u.id LEFT JOIN sys_user ru ON c.reply_to_user_id = ru.id WHERE c.parent_id IN
#{pid}
ORDER BY c.create_time ASC
